/* @autogenerated */
package net.civeira.phylax.feature.template.page.application;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.feature.identity.tenant.domain.Tenant;
import net.civeira.phylax.feature.identity.tenant.domain.TenantRef;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.feature.template.page.domain.DecoratedPage;
import net.civeira.phylax.feature.template.page.domain.PageDecoration;
import net.civeira.phylax.feature.template.render.application.usecase.render.TemplateRenderInput;
import net.civeira.phylax.feature.template.render.application.usecase.render.TemplateRenderUsecase;
import net.civeira.phylax.feature.template.render.domain.RenderedTemplate;
import net.civeira.phylax.feature.template.template.domain.TemplateChannelOptions;
import net.civeira.phylax.feature.template.theme.domain.Theme;
import net.civeira.phylax.feature.template.theme.domain.gateway.ThemeFilter;
import net.civeira.phylax.feature.template.theme.domain.gateway.ThemeQueryRepositoryGateway;
import net.civeira.phylax.feature.template.themeversion.domain.ThemeVersion;
import net.civeira.phylax.feature.template.themeversion.domain.ThemeVersionChannelOptions;
import net.civeira.phylax.feature.template.themeversion.domain.gateway.ThemeVersionFilter;
import net.civeira.phylax.feature.template.themeversion.domain.gateway.ThemeVersionQueryRepositoryGateway;

/**
 * Wraps HTML fragments in a full page with the active theme, for every feature that renders browser
 * pages (the OIDC flows, the observability viewer...).
 *
 * <p>
 * Two-step rendering:
 * <ol>
 * <li>Render the page template ({@link PageDecoration#getPageTemplate()}, channel HTML) with the
 * fragment as {@code innerContent}.</li>
 * <li>Wrap the result in the layout of the theme ({@code theme_version}, channel HTML) as
 * {@code slot_content}. The theme is the one of the tenant, or the global one; wide pages use the
 * companion theme {@code <theme>-full}.</li>
 * </ol>
 *
 * <p>
 * It does not build a fallback page: when no layout is found the result carries only the body and
 * the caller decides how to wrap it.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class PageDecorator {

  private final TemplateRenderUsecase renderUsecase;
  private final TenantQueryRepositoryGateway tenants;
  private final ThemeQueryRepositoryGateway themeGateway;
  private final ThemeVersionQueryRepositoryGateway themeVersionGateway;

  public DecoratedPage decorate(final PageDecoration request) {
    String tenantName = request.getTenant();
    // A null name would build an unfiltered query that matches every tenant.
    Optional<Tenant> tenantOpt = tenantName == null ? Optional.empty()
        : tenants.find(TenantFilter.builder().name(tenantName).build());
    Optional<Theme> themeOpt = tenantOpt.flatMap(this::resolveTheme).or(this::resolveGlobalTheme);
    String themeName = themeOpt.map(Theme::getName).orElse(request.getDefaultTheme());
    String themeAssetsPath = request.getAssetsBasePath() + "/" + themeName;

    Map<String, String> variables = new HashMap<>(request.getVariables());
    variables.put("title", request.getTitle());
    variables.put("theme_assets_path", themeAssetsPath);

    // Step 1 — render the page body template
    String pageBody = renderPageTemplate(request, tenantOpt, variables);

    // Step 2 — wrap in the theme layout. Full-window pages use a companion "<base-theme>-full"
    // layout theme.
    Optional<Theme> layoutThemeOpt = request.isWide() ? resolveFullLayoutTheme(themeOpt) : themeOpt;
    Optional<String> html = layoutThemeOpt
        .flatMap(theme -> renderThemeLayout(theme, request.getLocale(), pageBody, variables));
    if (html.isEmpty()) {
      log.debug("No theme layout found for theme='{}'", themeName);
    }
    return DecoratedPage.builder().html(html).body(pageBody).themeName(themeName)
        .themeAssetsPath(themeAssetsPath).build();
  }

  private String renderPageTemplate(final PageDecoration request, final Optional<Tenant> tenantOpt,
      final Map<String, String> variables) {
    Map<String, String> pageVariables = new HashMap<>(variables);
    pageVariables.put("innerContent", request.getInnerContent());
    Optional<RenderedTemplate> rendered = renderUsecase.render(TemplateRenderInput.builder()
        .code(request.getPageTemplate()).channel(TemplateChannelOptions.HTML)
        .tenant(tenantOpt.map(t -> (TenantRef) t).orElse(null)).locale(request.getLocale())
        .variables(pageVariables).build());
    return rendered.map(RenderedTemplate::getHtmlContent).orElseGet(() -> {
      log.debug("No '{}' page template found, using innerContent directly",
          request.getPageTemplate());
      return request.getInnerContent();
    });
  }

  private Optional<String> renderThemeLayout(final Theme theme, final Locale locale,
      final String slotContent, final Map<String, String> variables) {
    String localeTag = locale != null ? locale.toLanguageTag() : null;

    Optional<ThemeVersion> version =
        themeVersionGateway.list(ThemeVersionFilter.builder().theme(theme).build()).stream()
            .filter(v -> ThemeVersionChannelOptions.HTML == v.getChannel())
            .filter(v -> localeTag == null || localeTag.equals(v.getLocale().orElse(null))
                || v.getLocale().isEmpty())
            .findFirst();

    TenantRef tenantRef = theme.getTenant().orElse(null);
    Map<String, String> layoutVariables = new HashMap<>(variables);
    layoutVariables.put("slot_content", slotContent);
    return version.map(v -> {
      RenderedTemplate rendered =
          renderUsecase.renderHtml(v.getContentHtml(), tenantRef, locale, layoutVariables);
      return rendered.getHtmlContent();
    });
  }

  private Optional<Theme> resolveTheme(final Tenant tenant) {
    return themeGateway.list(ThemeFilter.builder().tenant(tenant).build()).stream()
        .filter(Theme::isEnabled).findFirst();
  }

  private Optional<Theme> resolveGlobalTheme() {
    return themeGateway.list(ThemeFilter.builder().global(true).build()).stream()
        .filter(Theme::isEnabled).filter(t -> !t.getName().endsWith("-full")).findFirst();
  }

  private Optional<Theme> resolveFullLayoutTheme(final Optional<Theme> baseTheme) {
    // Try "<base-theme-name>-full" first (e.g. "corporate" → "corporate-full")
    Optional<Theme> named = baseTheme.map(t -> t.getName() + "-full")
        .flatMap(fullName -> themeGateway.list(ThemeFilter.builder().name(fullName).build())
            .stream().filter(Theme::isEnabled).findFirst());
    if (named.isPresent()) {
      return named;
    }
    // Fallback: any global theme whose name ends with "-full"
    return themeGateway.list(ThemeFilter.builder().global(true).build()).stream()
        .filter(Theme::isEnabled).filter(t -> t.getName().endsWith("-full")).findFirst();
  }
}
